import{_ as i,a0 as l,w as p,s as r,I as e,x as a,a1 as n,A as o,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"如何使用 autofs 掛載 NFS 共享 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 autofs 掛載 NFS 共享 | LCTT (201905) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 autofs 掛載 NFS 共享 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 autofs 掛載 NFS 共享 | LCTT (201905) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201905/20180605 How to use autofs to mount NFS shares","title":"如何使用 autofs 掛載 NFS 共享","tag":"201905","desc":""},"relativePath":"201905/20180605 How to use autofs to mount NFS shares.md","filePath":"[post].md"}'),u={name:"201905/20180605 How to use autofs to mount NFS shares.md"};function c(h,s,g,k,f,m){const t=l("Link");return p(),r("div",null,[s[20]||(s[20]=e("h1",{id:"如何使用-autofs-掛載-nfs-共享",tabindex:"-1"},[a("如何使用 autofs 掛載 NFS 共享 "),e("a",{class:"header-anchor",href:"#如何使用-autofs-掛載-nfs-共享","aria-label":"Permalink to “如何使用 autofs 掛載 NFS 共享”"},"​")],-1)),s[21]||(s[21]=e("blockquote",null,[e("p",null,"給你的網絡文件系統（NFS）配置一個基本的自動掛載功能。")],-1)),s[22]||(s[22]=e("p",null,[e("img",{src:"https://img.linux.net.cn/data/attachment/album/201905/08/115328rva7kqw9wqh2qees.jpg",alt:""})],-1)),e("p",null,[s[1]||(s[1]=a("大多數 Linux 文件系統在引導時掛載，並在系統運行時保持掛載狀態。對於已在 ",-1)),s[2]||(s[2]=e("code",null,"fstab",-1)),s[3]||(s[3]=a(" 中配置的任何遠程文件系統也是如此。但是，有時你可能希望僅按需掛載遠程文件系統。例如，通過減少網絡帶寬使用來提高性能，或出於安全原因隱藏或混淆某些目錄。",-1)),n(t,{href:"https://wiki.archlinux.org/index.php/autofs"},{default:o(()=>[...s[0]||(s[0]=[a("autofs",-1)])]),_:1}),s[4]||(s[4]=a(" 軟件包提供此功能。在本文中，我將介紹如何配置基本的自動掛載。",-1))]),s[23]||(s[23]=d(`<p>首先做點假設：假設有台 NFS 服務器 <code>tree.mydatacenter.net</code> 已經啓動並運行。另外假設一個名為 <code>ourfiles</code> 的數據目錄還有供 Carl 和 Sarah 使用的用户目錄，它們都由服務器共享。</p><p>一些最佳實踐可以使工作更好：服務器上的用户和任何客户端工作站上的帳號有相同的用户 ID。此外，你的工作站和服務器應有相同的域名。檢查相關配置文件應該確認。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alan@workstation1:~$ sudo getent passwd carl sarah</span></span>
<span class="line"><span>[sudo] password for alan:</span></span>
<span class="line"><span>carl:x:1020:1020:Carl,,,:/home/carl:/bin/bash</span></span>
<span class="line"><span>sarah:x:1021:1021:Sarah,,,:/home/sarah:/bin/bash</span></span>
<span class="line"><span></span></span>
<span class="line"><span>alan@workstation1:~$ sudo getent hosts</span></span>
<span class="line"><span>127.0.0.1       localhost</span></span>
<span class="line"><span>127.0.1.1       workstation1.mydatacenter.net workstation1</span></span>
<span class="line"><span>10.10.1.5       tree.mydatacenter.net tree</span></span></code></pre></div><p>如你所見，客户端工作站和 NFS 服務器都在 <code>hosts</code> 文件中配置。我假設這是一個基本的家庭甚至小型辦公室網絡，可能缺乏適合的內部域名服務（即 DNS）。</p><h3 id="安裝軟件包" tabindex="-1">安裝軟件包 <a class="header-anchor" href="#安裝軟件包" aria-label="Permalink to “安裝軟件包”">​</a></h3><p>你只需要安裝兩個軟件包：用於 NFS 客户端的 <code>nfs-common</code> 和提供自動掛載的 <code>autofs</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alan@workstation1:~$ sudo apt-get install nfs-common autofs</span></span></code></pre></div><p>你可以驗證 autofs 相關的文件是否已放在 <code>/etc</code> 目錄中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alan@workstation1:~$ cd /etc; ll auto*</span></span>
<span class="line"><span>-rw-r--r-- 1 root root 12596 Nov 19  2015 autofs.conf</span></span>
<span class="line"><span>-rw-r--r-- 1 root root   857 Mar 10  2017 auto.master</span></span>
<span class="line"><span>-rw-r--r-- 1 root root   708 Jul  6  2017 auto.misc</span></span>
<span class="line"><span>-rwxr-xr-x 1 root root  1039 Nov 19  2015 auto.net*</span></span>
<span class="line"><span>-rwxr-xr-x 1 root root  2191 Nov 19  2015 auto.smb*</span></span>
<span class="line"><span>alan@workstation1:/etc$</span></span></code></pre></div><h3 id="配置-autofs" tabindex="-1">配置 autofs <a class="header-anchor" href="#配置-autofs" aria-label="Permalink to “配置 autofs”">​</a></h3><p>現在你需要編輯其中幾個文件並添加 <code>auto.home</code> 文件。首先，將以下兩行添加到文件 <code>auto.master</code> 中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/mnt/tree  /etc/auto.misc</span></span>
<span class="line"><span>/home/tree  /etc/auto.home</span></span></code></pre></div><p>每行以掛載 NFS 共享的目錄開頭。繼續創建這些目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alan@workstation1:/etc$ sudo mkdir /mnt/tree /home/tree</span></span></code></pre></div><p>接下來，將以下行添加到文件 <code>auto.misc</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ourfiles        -fstype=nfs     tree:/share/ourfiles</span></span></code></pre></div><p>該行表示 autofs 將掛載 <code>auto.master</code> 文件中匹配 <code>auto.misc</code> 的 <code>ourfiles</code> 共享。如上所示，這些文件將在 <code>/mnt/tree/ourfiles</code> 目錄中。</p><p>第三步，使用以下行創建文件 <code>auto.home</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>*               -fstype=nfs     tree:/home/&amp;</span></span></code></pre></div><p>該行表示 autofs 將掛載 <code>auto.master</code> 文件中匹配 <code>auto.home</code> 的用户共享。在這種情況下，Carl 和 Sarah 的文件將分別在目錄 <code>/home/tree/carl</code> 或 <code>/home/tree/sarah</code>中。星號 <code>*</code>（稱為通配符）使每個用户的共享可以在登錄時自動掛載。<code>＆</code> 符號也可以作為表示服務器端用户目錄的通配符。它們的主目錄會相應地根據 <code>passwd</code> 文件映射。如果你更喜歡本地主目錄，則無需執行此操作。相反，用户可以將其用作特定文件的簡單遠程存儲。</p><p>最後，重啓 <code>autofs</code> 守護進程，以便識別並加載這些配置的更改。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alan@workstation1:/etc$ sudo service autofs restart</span></span></code></pre></div><h3 id="測試-autofs" tabindex="-1">測試 autofs <a class="header-anchor" href="#測試-autofs" aria-label="Permalink to “測試 autofs”">​</a></h3><p>如果更改文件 <code>auto.master</code> 中的列出目錄，並運行 <code>ls</code> 命令，那麼不會立即看到任何內容。例如，切換到目錄 <code>/mnt/tree</code>。首先，<code>ls</code> 的輸出不會顯示任何內容，但在運行 <code>cd ourfiles</code> 之後，將自動掛載 <code>ourfiles</code> 共享目錄。 <code>cd</code> 命令也將被執行，你將進入新掛載的目錄中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>carl@workstation1:~$ cd /mnt/tree</span></span>
<span class="line"><span>carl@workstation1:/mnt/tree$ ls</span></span>
<span class="line"><span>carl@workstation1:/mnt/tree$ cd ourfiles</span></span>
<span class="line"><span>carl@workstation1:/mnt/tree/ourfiles$</span></span></code></pre></div><p>為了進一步確認正常工作，<code>mount</code> 命令會顯示已掛載共享的細節。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>carl@workstation1:~$ mount</span></span>
<span class="line"><span></span></span>
<span class="line"><span>tree:/mnt/share/ourfiles on /mnt/tree/ourfiles type nfs4 (rw,relatime,vers=4.0,rsize=131072,wsize=131072,namlen=255,hard,proto=tcp,timeo=600,retrans=2,sec=sys,clientaddr=10.10.1.22,local_lock=none,addr=10.10.1.5)</span></span></code></pre></div><p>對於 Carl 和 Sarah，<code>/home/tree</code> 目錄工作方式相同。</p><p>我發現在我的文件管理器中添加這些目錄的書籤很有用，可以用來快速訪問。</p><hr>`,30)),e("p",null,[s[6]||(s[6]=a("via: ",-1)),n(t,{href:"https://opensource.com/article/18/6/using-autofs-mount-nfs-shares"},{default:o(()=>[...s[5]||(s[5]=[a("https://opensource.com/article/18/6/using-autofs-mount-nfs-shares",-1)])]),_:1})]),e("p",null,[s[11]||(s[11]=a("作者：",-1)),n(t,{href:"https://opensource.com/users/alanfdoss"},{default:o(()=>[...s[7]||(s[7]=[a("Alan Formy-Duval",-1)])]),_:1}),s[12]||(s[12]=a(" 選題：",-1)),n(t,{href:"https://github.com/lujun9972"},{default:o(()=>[...s[8]||(s[8]=[a("lujun9972",-1)])]),_:1}),s[13]||(s[13]=a(" 譯者：",-1)),n(t,{href:"https://github.com/geekpi"},{default:o(()=>[...s[9]||(s[9]=[a("geekpi",-1)])]),_:1}),s[14]||(s[14]=a(" 校對：",-1)),n(t,{href:"https://github.com/wxy"},{default:o(()=>[...s[10]||(s[10]=[a("wxy",-1)])]),_:1})]),e("p",null,[s[17]||(s[17]=a("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...s[15]||(s[15]=[a("LCTT",-1)])]),_:1}),s[18]||(s[18]=a(" 原創編譯，",-1)),n(t,{href:"https://linux.cn/"},{default:o(()=>[...s[16]||(s[16]=[a("Linux中國",-1)])]),_:1}),s[19]||(s[19]=a(" 榮譽推出",-1))])])}const x=i(u,[["render",c]]);export{C as __pageData,x as default};
